codeExamples.tech1Snippet:
import { execFileSync } from "node:child_process";

const baseRevision = process.env.BASE_REVISION;
if (!baseRevision) throw new Error("BASE_REVISION is required for an affected build");
const changedPackagesFilter = "...[" + baseRevision + "]";

execFileSync(
  "turbo",
  ["run", "build", "--filter", changedPackagesFilter, "--concurrency=4"],
  { stdio: "inherit", env: { ...process.env, TURBO_TELEMETRY_DISABLED: "1" } },
);

codeExamples.tech2Snippet:
import { execFileSync } from "node:child_process";

const baseRevision = process.env.BASE_REVISION;
if (!baseRevision) throw new Error("BASE_REVISION is required for an affected build");

execFileSync(
  "nx",
  ["affected", "-t", "build", "--base", baseRevision, "--head", "HEAD", "--parallel=3"],
  { stdio: "inherit", env: { ...process.env, NX_DAEMON: "false" } },
);
